{
  "tenant": {
    "tenantType": "organization",
    "name": "{{tenantName}}",
    "description": "{{tenantName}} issuing and verification tenant",
    "slug": "{{tenantSlug}}",
    "initialPlatformSubdomain": true
  },
  "contacts": {
    "technical": {
      "email": "admin@{{tenantSlug}}.example",
      "displayName": "{{tenantName}} administrator"
    },
    "administrativeSameAsTechnical": true,
    "ownerAdmin": {
      "source": "technical"
    }
  },
  "login": {
    "enabled": true,
    "defaultAuthorizationServerRequired": true
  },
  "provisioning": {
    "issuer": true,
    "verifier": true,
    "keysAndDids": true,
    "sampleData": true
  }
}

{
  "tenant": {
    "tenantType": "organization",
    "name": "{{tenantName}} EU",
    "description": "{{tenantName}} EU child tenant",
    "slug": "{{tenantSlug}}-eu",
    "parentTenantId": "{{tenantId}}",
    "initialPlatformSubdomain": true
  },
  "contacts": {
    "technical": {
      "email": "admin@{{tenantSlug}}-eu.example",
      "displayName": "{{tenantName}} EU administrator"
    },
    "administrativeSameAsTechnical": true,
    "ownerAdmin": {
      "source": "technical"
    }
  },
  "login": {
    "enabled": true,
    "defaultAuthorizationServerRequired": true
  },
  "provisioning": {
    "issuer": true,
    "verifier": true,
    "keysAndDids": true,
    "sampleData": true
  }
}

{
  "alias": "employee-badge",
  "hostingMode": "LOCAL",
  "bindings": [
    {
      "vct": "EmployeeBadge",
      "vctHostingMode": "HOSTED",
      "credentialConfigurationId": "EmployeeBadge",
      "issuerId": "{{issuerId}}",
      "issuerUri": "{{credentialIssuer}}"
    }
  ],
  "credentialType": {
    "format": "SD_JWT_VC",
    "vct": "EmployeeBadge"
  },
  "displays": [
    {
      "locale": "en",
      "name": "Employee badge",
      "description": "Proves employment at {{tenantName}}"
    }
  ],
  "claims": [
    {
      "path": [
        {
          "type": "property",
          "name": "given_name"
        }
      ],
      "labels": [
        {
          "locale": "en",
          "label": "Given name"
        }
      ],
      "mandatory": true,
      "order": 1,
      "sdPolicy": "ALLOWED"
    },
    {
      "path": [
        {
          "type": "property",
          "name": "family_name"
        }
      ],
      "labels": [
        {
          "locale": "en",
          "label": "Family name"
        }
      ],
      "mandatory": true,
      "order": 2,
      "sdPolicy": "ALLOWED"
    },
    {
      "path": [
        {
          "type": "property",
          "name": "employee_id"
        }
      ],
      "labels": [
        {
          "locale": "en",
          "label": "Employee number"
        }
      ],
      "mandatory": true,
      "order": 3,
      "sdPolicy": "ALLOWED"
    }
  ]
}

{
  "queryId": "employee-badge",
  "name": "Employee badge",
  "description": "Name and employee number from the employee badge",
  "enabled": true,
  "dcqlQuery": {
    "credentials": [
      {
        "id": "badge",
        "format": "dc+sd-jwt",
        "meta": {
          "vct_values": [
            "https://{{tenantSlug}}.{{baseDomain}}/public/schema/vct/EmployeeBadge"
          ]
        },
        "claims": [
          {
            "path": [
              "given_name"
            ]
          },
          {
            "path": [
              "family_name"
            ]
          },
          {
            "path": [
              "employee_id"
            ]
          }
        ]
      }
    ]
  }
}
